#include <iostream>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

struct Battery {
    double p;
    double c;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    double d;
    if (!(cin >> n >> d)) return 0;

    vector<Battery> b(n);
    for (int i = 0; i < n; ++i) {
        cin >> b[i].p >> b[i].c;
    }

    // dp[i] armazenará o tempo mínimo para chegar à posição b[i].p
    // O destino final é a posição D, que podemos tratar como o índice n
    vector<double> dp(n + 1, 1e18);
    dp[0] = 0.0;

    for (int i = 0; i < n; ++i) {
        // Tentar ir da bateria i até qualquer bateria j futura
        for (int j = i + 1; j < n; ++j) {
            double dist = b[j].p - b[i].p;
            double time = (dist * dist) / b[i].c;
            if (dp[i] + time < dp[j]) {
                dp[j] = dp[i] + time;
            }
        }
        // Tentar ir da bateria i direto até o final D
        double dist = d - b[i].p;
        double time = (dist * dist) / b[i].c;
        if (dp[i] + time < dp[n]) {
            dp[n] = dp[i] + time;
        }
    }

    cout << fixed << setprecision(3) << dp[n] << "\n";

    return 0;
}
